INSERT IGNORE INTO graha_bhava_rashi (graha_id, bhava_id, rashi_id, interpretation_np, interpretation_en, positive_effects, challenges, career_indication, financial_indication, relationship_indication, classical_interpretation, sanskrit_reference, remedies) VALUES
(4,1,1,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, साहस','द्विधा, अति चिन्ता, शंकाग्रस्त मन, जल्दबाजी','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, आत्मप्रयासबाट आय','संवाद क्षमताले सम्बन्ध सुधार, ऊर्जावान तर धैर्य कम','बुधो लग्ने वाक्पटुतां ददाति। बुधो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,2,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, धैर्य','द्विधा, अति चिन्ता, शंकाग्रस्त मन, जिद','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, बचत र भूमि लाभ','संवाद क्षमताले सम्बन्ध सुधार, वफादार र शान्त','बुधो लग्ने वाक्पटुतां ददाति। बुधो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,3,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, वाणी','द्विधा, अति चिन्ता, शंकाग्रस्त मन, अस्थिरता','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, बहुआय, अनियमित','संवाद क्षमताले सम्बन्ध सुधार, मैत्रीपूर्ण तर भावना चञ्चल','बुधो लग्ने वाक्पटुतां ददाति। बुधो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,4,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, करुणा','द्विधा, अति चिन्ता, शंकाग्रस्त मन, मनोद्वन्द्व','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, चल सम्पत्ति, जलजन्य आय','संवाद क्षमताले सम्बन्ध सुधार, गहिरो स्नेह र ममता','बुधो लग्ने वाक्पटुतां ददाति। बुधो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,5,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, नेतृत्व','द्विधा, अति चिन्ता, शंकाग्रस्त मन, अहंकार','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','संवाद क्षमताले सम्बन्ध सुधार, आदर चाहने, उदार','बुधो लग्ने वाक्पटुतां ददाति। बुधो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,6,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, विश्लेषण','द्विधा, अति चिन्ता, शंकाग्रस्त मन, आलोचनात्मकता','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, योजनाबद्ध बचत','संवाद क्षमताले सम्बन्ध सुधार, व्यावहारिक स्नेह, सेवा','बुधो लग्ने वाक्पटुतां ददाति। बुधो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,7,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, न्याय','द्विधा, अति चिन्ता, शंकाग्रस्त मन, निर्णय ढिलाइ','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, सन्तुलित आय','संवाद क्षमताले सम्बन्ध सुधार, सामञ्जस्यपूर्ण जीवनसाथी','बुधो लग्ने वाक्पटुतां ददाति। बुधो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,8,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, अन्तर्दृष्टि','द्विधा, अति चिन्ता, शंकाग्रस्त मन, षड्यन्त्रवाद','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, अचानक उतारचढाव','संवाद क्षमताले सम्बन्ध सुधार, गहिरो तर तीव्र','बुधो लग्ने वाक्पटुतां ददाति। बुधो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,9,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, ज्ञान','द्विधा, अति चिन्ता, शंकाग्रस्त मन, अति विश्वास','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, भाग्यबाट लाभ, उदार खर्च','संवाद क्षमताले सम्बन्ध सुधार, स्वतन्त्रता दिने','बुधो लग्ने वाक्पटुतां ददाति। बुधो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,10,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, कर्मठता','द्विधा, अति चिन्ता, शंकाग्रस्त मन, निराशावाद','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, हौले हौले सम्पत्ति','संवाद क्षमताले सम्बन्ध सुधार, जिम्मेवार तर शब्द कम','बुधो लग्ने वाक्पटुतां ददाति। बुधो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,11,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, नवप्रवर्तन','द्विधा, अति चिन्ता, शंकाग्रस्त मन, विद्रोहीपन','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, नवीन तर अनियमित स्रोत','संवाद क्षमताले सम्बन्ध सुधार, मित्रतामा आधारित','बुधो लग्ने वाक्पटुतां ददाति। बुधो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,1,12,'बुध लग्नमा बुद्धिमान, सञ्चारमा दक्ष र चतुर बनाउँछ। तर्कशक्ति र शिक्षाप्रिय स्वभाव हुन्छ। बुधको मीन राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक चतुराई, शिक्षा, कल्पनाशक्ति','द्विधा, अति चिन्ता, शंकाग्रस्त मन, अस्पष्टता','व्यापार, लेखन, शिक्षण, प्राविधिक काम','व्यापारबाट नियमित आय, स्रोत अनिश्चित, दानशीलता','संवाद क्षमताले सम्बन्ध सुधार, निःशर्त प्रेम, बलिदान','बुधो लग्ने वाक्पटुतां ददाति। बुधो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गायलाई हरियो घाँस खुवाउने।'),
(4,2,1,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, साहस','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, जल्दबाजी','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, आत्मप्रयासबाट आय','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, ऊर्जावान तर धैर्य कम','द्वितीयस्थो बुधो धनवान् भवति। बुधो मेषे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,2,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, धैर्य','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, जिद','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, बचत र भूमि लाभ','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, वफादार र शान्त','द्वितीयस्थो बुधो धनवान् भवति। बुधो वृषभे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,3,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, वाणी','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, द्विधा','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, बहुआय','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, मैत्रीपूर्ण तर भावना चञ्चल','द्वितीयस्थो बुधो धनवान् भवति। बुधो मिथुने फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,4,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, करुणा','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, मनोद्वन्द्व','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, चल सम्पत्ति','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, गहिरो स्नेह र ममता','द्वितीयस्थो बुधो धनवान् भवति। बुधो कर्के फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,5,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, नेतृत्व','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, अहंकार','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, आदर चाहने, उदार','द्वितीयस्थो बुधो धनवान् भवति। बुधो सिंहे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,6,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, विश्लेषण','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, आलोचनात्मकता','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, योजनाबद्ध बचत','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, व्यावहारिक स्नेह, सेवा','द्वितीयस्थो बुधो धनवान् भवति। बुधो कन्यायां फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,7,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, न्याय','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, निर्णय ढिलाइ','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, सन्तुलित आय','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, सामञ्जस्यपूर्ण जीवनसाथी','द्वितीयस्थो बुधो धनवान् भवति। बुधो तुलायां फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,8,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, अन्तर्दृष्टि','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, षड्यन्त्रवाद','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, अचानक उतारचढाव','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, गहिरो तर तीव्र','द्वितीयस्थो बुधो धनवान् भवति। बुधो वृश्चिके फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,9,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, ज्ञान','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, अति विश्वास','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, भाग्यबाट लाभ','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, स्वतन्त्रता दिने','द्वितीयस्थो बुधो धनवान् भवति। बुधो धनौ फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,10,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, कर्मठता','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, निराशावाद','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, हौले हौले सम्पत्ति','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, जिम्मेवार तर शब्द कम','द्वितीयस्थो बुधो धनवान् भवति। बुधो मकरे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,11,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, नवप्रवर्तन','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, विद्रोहीपन','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, नवीन तर अनियमित स्रोत','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, मित्रतामा आधारित','द्वितीयस्थो बुधो धनवान् भवति। बुधो कुम्भे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,2,12,'बुध दोस्रो भावमा वाणी र धन दुवैमा चतुरता ल्याउँछ। व्यापार, लेखन र गणितबाट आय आउँछ। पैसा बचत गर्ने बुद्धि हुन्छ तर कहिलेकाहीँ एउटै ठाउँबाट धेरै स्रोत खोज्ने डरावट देखिन्छ। बुधको मीन राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'वाणी चतुरता, व्यापार बुद्धि, बचत क्षमता, लेखन कौशल, कल्पनाशक्ति','अति विश्लेषण, वाणीमा डरावट, पैसामा दोहोरो विचार, अस्पष्टता','व्यापार, लेखन, लेखा, परामर्श','छोटो अवधिमा लाभ, तर बहुआयामिक आय, स्रोत अनिश्चित','परिवारसँग बुद्धिमत्तापूर्ण व्यवहार, निःशर्त प्रेम, बलिदान','द्वितीयस्थो बुधो धनवान् भवति। बुधो मीने फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित वस्त्र दान।'),
(4,3,1,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, साहस','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, जल्दबाजी','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, आत्मप्रयासबाट आय','भाइबहिनीसँग बौद्धिक आदानप्रदान, ऊर्जावान तर धैर्य कम','तृतीयस्थो बुधो वाक्पटु भवति। बुधो मेषे फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,2,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, धैर्य','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, जिद','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, बचत र भूमि लाभ','भाइबहिनीसँग बौद्धिक आदानप्रदान, वफादार र शान्त','तृतीयस्थो बुधो वाक्पटु भवति। बुधो वृषभे फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,3,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, वाणी','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, द्विधा','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, बहुआय, अनियमित','भाइबहिनीसँग बौद्धिक आदानप्रदान, मैत्रीपूर्ण तर भावना चञ्चल','तृतीयस्थो बुधो वाक्पटु भवति। बुधो मिथुने फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,4,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, करुणा','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, मनोद्वन्द्व','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, चल सम्पत्ति, जलजन्य आय','भाइबहिनीसँग बौद्धिक आदानप्रदान, गहिरो स्नेह र ममता','तृतीयस्थो बुधो वाक्पटु भवति। बुधो कर्के फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,5,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, नेतृत्व','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, अहंकार','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','भाइबहिनीसँग बौद्धिक आदानप्रदान, आदर चाहने, उदार','तृतीयस्थो बुधो वाक्पटु भवति। बुधो सिंहे फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,6,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, विश्लेषण','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, आलोचनात्मकता','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, योजनाबद्ध बचत','भाइबहिनीसँग बौद्धिक आदानप्रदान, व्यावहारिक स्नेह, सेवा','तृतीयस्थो बुधो वाक्पटु भवति। बुधो कन्यायां फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,7,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, न्याय','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, निर्णय ढिलाइ','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, सन्तुलित आय','भाइबहिनीसँग बौद्धिक आदानप्रदान, सामञ्जस्यपूर्ण जीवनसाथी','तृतीयस्थो बुधो वाक्पटु भवति। बुधो तुलायां फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,8,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, अन्तर्दृष्टि','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, षड्यन्त्रवाद','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, अचानक उतारचढाव','भाइबहिनीसँग बौद्धिक आदानप्रदान, गहिरो तर तीव्र','तृतीयस्थो बुधो वाक्पटु भवति। बुधो वृश्चिके फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,9,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, ज्ञान','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, अति विश्वास','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, भाग्यबाट लाभ, उदार खर्च','भाइबहिनीसँग बौद्धिक आदानप्रदान, स्वतन्त्रता दिने','तृतीयस्थो बुधो वाक्पटु भवति। बुधो धनौ फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,10,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, कर्मठता','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, निराशावाद','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, हौले हौले सम्पत्ति','भाइबहिनीसँग बौद्धिक आदानप्रदान, जिम्मेवार तर शब्द कम','तृतीयस्थो बुधो वाक्पटु भवति। बुधो मकरे फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,11,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, नवप्रवर्तन','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, विद्रोहीपन','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, नवीन तर अनियमित स्रोत','भाइबहिनीसँग बौद्धिक आदानप्रदान, मित्रतामा आधारित','तृतीयस्थो बुधो वाक्पटु भवति। बुधो कुम्भे फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,3,12,'बुध तेस्रो भावमा सञ्चार र लेखनमा प्रतिभा दिन्छ। छोटो यात्रामा व्यापारिक लाभ हुन्छ। भाइबहिनीसँग बुद्धिमत्ता साझेदारी रहन्छ तर कहिलेकाहीँ एकै कुरा दोहोर्याउने बानी लाग्छ। बुधको मीन राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'सञ्चार कौशल, लेखन प्रतिभा, यात्रामा व्यापार, भाइबहिनी बुद्धि, कल्पनाशक्ति','अति बोल्ने बानी, दोहोरो कुरा, अधुरो विचार, अस्पष्टता','पत्रकारिता, विपणन, अनुवाद, यात्रा व्यापार','छोटो यात्रा र सञ्चारबाट लाभ, स्रोत अनिश्चित, दानशीलता','भाइबहिनीसँग बौद्धिक आदानप्रदान, निःशर्त प्रेम, बलिदान','तृतीयस्थो बुधो वाक्पटु भवति। बुधो मीने फलं वर्धयति।','Brihat Jataka','बुधवार गणेश मन्त्र जप र दूर्वा अर्पण।'),
(4,4,1,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, साहस','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, जल्दबाजी','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, आत्मप्रयासबाट आय','परिवारसँग बुद्धिमय सम्बन्ध, ऊर्जावान तर धैर्य कम','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो मेषे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,2,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, धैर्य','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, जिद','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, बचत र भूमि लाभ','परिवारसँग बुद्धिमय सम्बन्ध, वफादार र शान्त','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो वृषभे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,3,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, वाणी','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, द्विधा','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, बहुआय, अनियमित','परिवारसँग बुद्धिमय सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो मिथुने फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,4,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, करुणा','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, मनोद्वन्द्व','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, चल सम्पत्ति, जलजन्य आय','परिवारसँग बुद्धिमय सम्बन्ध, गहिरो स्नेह र ममता','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो कर्के फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,5,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, नेतृत्व','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, अहंकार','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','परिवारसँग बुद्धिमय सम्बन्ध, आदर चाहने, उदार','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो सिंहे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,6,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, विश्लेषण','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, आलोचनात्मकता','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, योजनाबद्ध बचत','परिवारसँग बुद्धिमय सम्बन्ध, व्यावहारिक स्नेह, सेवा','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो कन्यायां फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,7,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, न्याय','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, निर्णय ढिलाइ','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, सन्तुलित आय','परिवारसँग बुद्धिमय सम्बन्ध, सामञ्जस्यपूर्ण जीवनसाथी','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो तुलायां फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,8,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, अन्तर्दृष्टि','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, षड्यन्त्रवाद','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, अचानक उतारचढाव','परिवारसँग बुद्धिमय सम्बन्ध, गहिरो तर तीव्र','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो वृश्चिके फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,9,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, ज्ञान','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, अति विश्वास','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, भाग्यबाट लाभ, उदार खर्च','परिवारसँग बुद्धिमय सम्बन्ध, स्वतन्त्रता दिने','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो धनौ फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,10,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, कर्मठता','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, निराशावाद','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, हौले हौले सम्पत्ति','परिवारसँग बुद्धिमय सम्बन्ध, जिम्मेवार तर शब्द कम','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो मकरे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,11,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, नवप्रवर्तन','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, विद्रोहीपन','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, नवीन तर अनियमित स्रोत','परिवारसँग बुद्धिमय सम्बन्ध, मित्रतामा आधारित','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो कुम्भे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,4,12,'बुध चौथो भावमा बौद्धिक सुख र शिक्षामा सफलता दिन्छ। घरमा पुस्तक र ज्ञानको वातावरण रहन्छ। वाहन र सम्पत्तिमा व्यावहारिकता रहन्छ तर मन एउटै ठाउँमा टिक्न नसक्ने हुन्छ। बुधको मीन राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'शिक्षा सुख, घरमा ज्ञान, व्यावहारिक सम्पत्ति, वाहन सुख, कल्पनाशक्ति','मन डोलने प्रवृत्ति, चिन्ता, घरमा अस्थिरता, अस्पष्टता','शिक्षण, प्रकाशन, सल्लाह, भवन व्यवसाय','शिक्षा र लेखनबाट स्थिर आय, स्रोत अनिश्चित, दानशीलता','परिवारसँग बुद्धिमय सम्बन्ध, निःशर्त प्रेम, बलिदान','चतुर्थस्थो बुधो विद्यावान् भवति। बुधो मीने फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र घरमा विद्या दीप प्रज्वलन।'),
(4,5,1,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, साहस','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, जल्दबाजी','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, आत्मप्रयासबाट आय','सन्तान र शिष्यसँग बौद्धिक जडान, ऊर्जावान तर धैर्य कम','पञ्चमस्थो बुधो मेधावी भवति। बुधो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,2,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, धैर्य','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, जिद','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, बचत र भूमि लाभ','सन्तान र शिष्यसँग बौद्धिक जडान, वफादार र शान्त','पञ्चमस्थो बुधो मेधावी भवति। बुधो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,3,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, वाणी','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, द्विधा','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, बहुआय, अनियमित','सन्तान र शिष्यसँग बौद्धिक जडान, मैत्रीपूर्ण तर भावना चञ्चल','पञ्चमस्थो बुधो मेधावी भवति। बुधो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,4,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, करुणा','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, मनोद्वन्द्व','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, चल सम्पत्ति, जलजन्य आय','सन्तान र शिष्यसँग बौद्धिक जडान, गहिरो स्नेह र ममता','पञ्चमस्थो बुधो मेधावी भवति। बुधो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,5,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, नेतृत्व','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, अहंकार','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','सन्तान र शिष्यसँग बौद्धिक जडान, आदर चाहने, उदार','पञ्चमस्थो बुधो मेधावी भवति। बुधो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,6,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, विश्लेषण','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, आलोचनात्मकता','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, योजनाबद्ध बचत','सन्तान र शिष्यसँग बौद्धिक जडान, व्यावहारिक स्नेह, सेवा','पञ्चमस्थो बुधो मेधावी भवति। बुधो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,7,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, न्याय','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, निर्णय ढिलाइ','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, सन्तुलित आय','सन्तान र शिष्यसँग बौद्धिक जडान, सामञ्जस्यपूर्ण जीवनसाथी','पञ्चमस्थो बुधो मेधावी भवति। बुधो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,8,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, अन्तर्दृष्टि','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, षड्यन्त्रवाद','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, अचानक उतारचढाव','सन्तान र शिष्यसँग बौद्धिक जडान, गहिरो तर तीव्र','पञ्चमस्थो बुधो मेधावी भवति। बुधो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,9,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, ज्ञान','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, अति विश्वास','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, भाग्यबाट लाभ, उदार खर्च','सन्तान र शिष्यसँग बौद्धिक जडान, स्वतन्त्रता दिने','पञ्चमस्थो बुधो मेधावी भवति। बुधो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,10,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, कर्मठता','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, निराशावाद','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, हौले हौले सम्पत्ति','सन्तान र शिष्यसँग बौद्धिक जडान, जिम्मेवार तर शब्द कम','पञ्चमस्थो बुधो मेधावी भवति। बुधो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,11,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, नवप्रवर्तन','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, विद्रोहीपन','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, नवीन तर अनियमित स्रोत','सन्तान र शिष्यसँग बौद्धिक जडान, मित्रतामा आधारित','पञ्चमस्थो बुधो मेधावी भवति। बुधो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,5,12,'बुध पाँचौं भावमा तीव्र बुद्धि र शिक्षामा उत्कृष्टता दिन्छ। व्यापारमा अटकलबाजीबाट सोच-विचार गरेर लाभ हुन्छ। सन्तान बुद्धिमान हुन्छन् र विद्यार्थी जीवनमा ख्याति पाइन्छ। बुधको मीन राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, शिक्षामा उत्कृष्टता, बुद्धिमान सन्तान, विश्लेषण क्षमता, कल्पनाशक्ति','अति विश्लेषण, निर्णयमा ढिलाइ, वादविवाद, अस्पष्टता','शिक्षण, अनुसन्धान, व्यापार, सूचना प्रविधि','सोच-विचार गरी लगानीमा लाभ, स्रोत अनिश्चित, दानशीलता','सन्तान र शिष्यसँग बौद्धिक जडान, निःशर्त प्रेम, बलिदान','पञ्चमस्थो बुधो मेधावी भवति। बुधो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra','बुधवार गणेश मन्त्र जप र विद्यार्थीलाई दान।'),
(4,6,1,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, साहस','नसाको तनाव, अति चिन्ता, वाणी विवाद, जल्दबाजी','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, आत्मप्रयासबाट आय','सहकर्मीसँग बुद्धिमत्ता व्यवहार, ऊर्जावान तर धैर्य कम','षष्ठस्थो बुधो रिपुं विजयति। बुधो मेषे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,2,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, धैर्य','नसाको तनाव, अति चिन्ता, वाणी विवाद, जिद','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, बचत र भूमि लाभ','सहकर्मीसँग बुद्धिमत्ता व्यवहार, वफादार र शान्त','षष्ठस्थो बुधो रिपुं विजयति। बुधो वृषभे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,3,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, वाणी','नसाको तनाव, अति चिन्ता, वाणी विवाद, द्विधा','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, बहुआय','सहकर्मीसँग बुद्धिमत्ता व्यवहार, मैत्रीपूर्ण तर भावना चञ्चल','षष्ठस्थो बुधो रिपुं विजयति। बुधो मिथुने फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,4,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, करुणा','नसाको तनाव, अति चिन्ता, वाणी विवाद, मनोद्वन्द्व','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, चल सम्पत्ति','सहकर्मीसँग बुद्धिमत्ता व्यवहार, गहिरो स्नेह र ममता','षष्ठस्थो बुधो रिपुं विजयति। बुधो कर्के फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,5,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, नेतृत्व','नसाको तनाव, अति चिन्ता, वाणी विवाद, अहंकार','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','सहकर्मीसँग बुद्धिमत्ता व्यवहार, आदर चाहने, उदार','षष्ठस्थो बुधो रिपुं विजयति। बुधो सिंहे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,6,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, विश्लेषण','नसाको तनाव, अति चिन्ता, वाणी विवाद, आलोचनात्मकता','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, योजनाबद्ध बचत','सहकर्मीसँग बुद्धिमत्ता व्यवहार, व्यावहारिक स्नेह, सेवा','षष्ठस्थो बुधो रिपुं विजयति। बुधो कन्यायां फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,7,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, न्याय','नसाको तनाव, अति चिन्ता, वाणी विवाद, निर्णय ढिलाइ','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, सन्तुलित आय','सहकर्मीसँग बुद्धिमत्ता व्यवहार, सामञ्जस्यपूर्ण जीवनसाथी','षष्ठस्थो बुधो रिपुं विजयति। बुधो तुलायां फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,8,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, अन्तर्दृष्टि','नसाको तनाव, अति चिन्ता, वाणी विवाद, षड्यन्त्रवाद','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, अचानक उतारचढाव','सहकर्मीसँग बुद्धिमत्ता व्यवहार, गहिरो तर तीव्र','षष्ठस्थो बुधो रिपुं विजयति। बुधो वृश्चिके फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,9,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, ज्ञान','नसाको तनाव, अति चिन्ता, वाणी विवाद, अति विश्वास','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, भाग्यबाट लाभ','सहकर्मीसँग बुद्धिमत्ता व्यवहार, स्वतन्त्रता दिने','षष्ठस्थो बुधो रिपुं विजयति। बुधो धनौ फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,10,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, कर्मठता','नसाको तनाव, अति चिन्ता, वाणी विवाद, निराशावाद','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, हौले हौले सम्पत्ति','सहकर्मीसँग बुद्धिमत्ता व्यवहार, जिम्मेवार तर शब्द कम','षष्ठस्थो बुधो रिपुं विजयति। बुधो मकरे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,11,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, नवप्रवर्तन','नसाको तनाव, अति चिन्ता, वाणी विवाद, विद्रोहीपन','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, नवीन तर अनियमित स्रोत','सहकर्मीसँग बुद्धिमत्ता व्यवहार, मित्रतामा आधारित','षष्ठस्थो बुधो रिपुं विजयति। बुधो कुम्भे फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,6,12,'बुध छैटौं भावमा बुद्धि र वाणीले शत्रुलाई परास्त गर्न सिकाउँछ। सेवा र व्यापारमा प्रतिष्ठा मिल्छ। तनाव र नसाको समस्या हुन सक्छ, तर समस्या समाधानमा निपुण हुन्छन्। बुधको मीन राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय (बुद्धिले), सेवा प्रतिष्ठा, समस्या समाधान, व्यापार विजय, कल्पनाशक्ति','नसाको तनाव, अति चिन्ता, वाणी विवाद, अस्पष्टता','लेखा, परामर्श, स्वास्थ्य सेवा, व्यापार','ऋण फिर्ता, व्यापारबाट नियमित आय, स्रोत अनिश्चित','सहकर्मीसँग बुद्धिमत्ता व्यवहार, निःशर्त प्रेम, बलिदान','षष्ठस्थो बुधो रिपुं विजयति। बुधो मीने फलं वर्धयति।','Phaladeepika','बुधवार गणेश मन्त्र जप र हरित दान।'),
(4,7,1,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, साहस, नेतृत्व','शंका, अनावश्यक तर्क, भावना कम, जल्दबाजी','व्यापारिक साझेदारी, सल्लाहकार काम, सेना, खेलकुद','साझेदारीबाट लाभ, आत्मप्रयासबाट आय','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, ऊर्जावान तर धैर्य कम','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,2,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, धैर्य, संचय','शंका, अनावश्यक तर्क, भावना कम, जिद','व्यापारिक साझेदारी, सल्लाहकार काम, कृषि, बैंक','साझेदारीबाट लाभ, बचत र भूमि लाभ','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, वफादार र शान्त','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,3,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, वाणी, बुद्धि','शंका, अनावश्यक तर्क, भावना कम, द्विधा','व्यापारिक साझेदारी, सल्लाहकार काम, लेखन, सञ्चार','साझेदारीबाट लाभ, बहुआय, अनियमित','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, मैत्रीपूर्ण तर भावना चञ्चल','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,4,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, करुणा, स्मृति','शंका, अनावश्यक तर्क, भावना कम, मनोद्वन्द्व','व्यापारिक साझेदारी, सल्लाहकार काम, खाद्य, शिक्षा','साझेदारीबाट लाभ, चल सम्पत्ति, जलजन्य आय','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, गहिरो स्नेह र ममता','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,5,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, नेतृत्व, दानशीलता','शंका, अनावश्यक तर्क, भावना कम, अहंकार','व्यापारिक साझेदारी, सल्लाहकार काम, प्रशासन, कला','साझेदारीबाट लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, आदर चाहने, उदार','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,6,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, विश्लेषण, शुद्धता','शंका, अनावश्यक तर्क, भावना कम, आलोचनात्मकता','व्यापारिक साझेदारी, सल्लाहकार काम, चिकित्सा, लेखा','साझेदारीबाट लाभ, योजनाबद्ध बचत','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, व्यावहारिक स्नेह, सेवा','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,7,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, न्याय, सौन्दर्य','शंका, अनावश्यक तर्क, भावना कम, निर्णय ढिलाइ','व्यापारिक साझेदारी, सल्लाहकार काम, कानुन, कला','साझेदारीबाट लाभ, सन्तुलित आय','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, सामञ्जस्यपूर्ण जीवनसाथी','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,8,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, अन्तर्दृष्टि, परिवर्तन','शंका, अनावश्यक तर्क, भावना कम, षड्यन्त्रवाद','व्यापारिक साझेदारी, सल्लाहकार काम, अनुसन्धान, सुरक्षा','साझेदारीबाट लाभ, अचानक उतारचढाव','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, गहिरो तर तीव्र','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,9,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, ज्ञान, आशावाद','शंका, अनावश्यक तर्क, भावना कम, अति विश्वास','व्यापारिक साझेदारी, सल्लाहकार काम, शिक्षण, धर्म','साझेदारीबाट लाभ, भाग्यबाट लाभ, उदार खर्च','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, स्वतन्त्रता दिने','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,10,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, कर्मठता, धैर्य','शंका, अनावश्यक तर्क, भावना कम, निराशावाद','व्यापारिक साझेदारी, सल्लाहकार काम, प्रशासन, व्यवस्थापन','साझेदारीबाट लाभ, हौले हौले सम्पत्ति','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, जिम्मेवार तर शब्द कम','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,11,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, नवप्रवर्तन, मित्रता','शंका, अनावश्यक तर्क, भावना कम, विद्रोहीपन','व्यापारिक साझेदारी, सल्लाहकार काम, प्रविधि, विज्ञान','साझेदारीबाट लाभ, नवीन तर अनियमित स्रोत','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, मित्रतामा आधारित','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,12,'बुध सप्तम भावमा बुद्धिमान र संवादप्रिय जीवनसाथी दिन्छ। विवाहमा सामञ्जस्य र सहभागिता हुन्छ। बुधको मीन राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'बुद्धिमान जीवनसाथी, संवाद सुधार, साझेदारीमा लाभ, कल्पनाशक्ति, करुणा','शंका, अनावश्यक तर्क, भावना कम, अस्पष्टता','व्यापारिक साझेदारी, सल्लाहकार काम, कला, सेवा','साझेदारीबाट लाभ, स्रोत अनिश्चित, दानशीलता','सामञ्जस्यपूर्ण तर कहिलेकाहीं अलगाव, निःशर्त प्रेम, बलिदान','सप्तमे बुधो मित्रवत् स्वामीं ददाति। बुधो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,8,1,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, साहस','नसाको तनाव, अचानक चिन्ता, गोपनीयता, जल्दबाजी','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, आत्मप्रयासबाट आय','गोपनीय सूचना र गम्भीर विचार, ऊर्जावान तर धैर्य कम','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो मेषे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
(4,8,2,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, धैर्य','नसाको तनाव, अचानक चिन्ता, गोपनीयता, जिद','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, बचत र भूमि लाभ','गोपनीय सूचना र गम्भीर विचार, वफादार र शान्त','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो वृषभे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
(4,8,3,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको मिथुन राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, वाणी','नसाको तनाव, अचानक चिन्ता, गोपनीयता, द्विधा','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, बहुआय','गोपनीय सूचना र गम्भीर विचार, मैत्रीपूर्ण तर भावना चञ्चल','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो मिथुने फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
(4,8,4,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, करुणा','नसाको तनाव, अचानक चिन्ता, गोपनीयता, मनोद्वन्द्व','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, चल सम्पत्ति','गोपनीय सूचना र गम्भीर विचार, गहिरो स्नेह र ममता','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो कर्के फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
(4,8,5,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, नेतृत्व','नसाको तनाव, अचानक चिन्ता, गोपनीयता, अहंकार','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, उदार खर्चसँगै प्रतिष्ठाजनक आय','गोपनीय सूचना र गम्भीर विचार, आदर चाहने, उदार','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो सिंहे फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
(4,8,6,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको कन्या राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, विश्लेषण','नसाको तनाव, अचानक चिन्ता, गोपनीयता, आलोचनात्मकता','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, योजनाबद्ध बचत','गोपनीय सूचना र गम्भीर विचार, व्यावहारिक स्नेह, सेवा','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो कन्यायां फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
(4,8,7,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, न्याय','नसाको तनाव, अचानक चिन्ता, गोपनीयता, निर्णय ढिलाइ','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, सन्तुलित आय','गोपनीय सूचना र गम्भीर विचार, सामञ्जस्यपूर्ण जीवनसाथी','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो तुलायां फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
(4,8,8,'बुध आउठौं भावमा अनुसन्धान र रहस्य ज्ञानमा गहिराइ दिन्छ। विरासत र लेखाजोखाबाट लाभ हुन सक्छ। नसा र मानसिक तनावमा सावधानी चाहिन्छ, तर जटिल कुरा बुझ्ने क्षमता असाधारण हुन्छ। बुधको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, लेखा कौशल, विरासत लाभ, अन्तर्दृष्टि','नसाको तनाव, अचानक चिन्ता, गोपनीयता, षड्यन्त्रवाद','अनुसन्धान, कर लेखा, प्रविधि, ज्योतिष','विरासत र छानबिनबाट लाभ, तर जोखिम पनि, अचानक उतारचढाव','गोपनीय सूचना र गम्भीर विचार, गहिरो तर तीव्र','अष्टमस्थो बुधो गूढज्ञो भवति। बुधो वृश्चिके फलं वर्धयति।','Saravali','बुधवार गणेश मन्त्र जप र शिवलिङ्गमा जल।'),
